<script setup lang="ts">import {onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase';import {useAuth} from '@/stores/auth'
const auth=useAuth(),data=ref({cashSales:0,creditSales:0,customerOwed:0,creditorOwed:0,expenses:0,stockCost:null as number|null}),error=ref(''),loading=ref(true)
function print(){window.print()}
onMounted(async()=>{const [s,c,v,e]=await Promise.all([supabase.from('sales').select('grand_total,payment_method'),supabase.from('credits').select('balance').eq('status','open'),supabase.from('creditors').select('balance'),supabase.from('expenses').select('amount')]);for(const r of [s,c,v,e])if(r.error){error.value=r.error.message;loading.value=false;return}let stockCost:number|null=null;if(auth.isAdmin||auth.profile?.caps.includes('view_costs')){const {data:pdata,error:pe}=await supabase.rpc('inventory_value');if(pe)error.value=pe.message;else stockCost=Number(pdata??0)}data.value={cashSales:s.data.filter(x=>x.payment_method==='cash').reduce((a,x)=>a+Number(x.grand_total||0),0),creditSales:s.data.filter(x=>x.payment_method==='credit').reduce((a,x)=>a+Number(x.grand_total||0),0),customerOwed:c.data.reduce((a,x)=>a+Number(x.balance||0),0),creditorOwed:v.data.reduce((a,x)=>a+Number(x.balance||0),0),expenses:e.data.reduce((a,x)=>a+Number(x.amount||0),0),stockCost};loading.value=false})
</script><template><section class="page-wrap"><div class="page-heading"><div><h1>Business balance</h1><p>Current receivables, payables, stock value and recorded expenses.</p></div><button class="btn" @click="print">Print / Save PDF</button></div><p v-if="error" class="alert">{{error}}</p><p v-if="loading" class="empty">Calculating balance…</p><div v-else class="stats-grid"><article class="stat"><span>Cash sales recorded</span><strong>UGX {{data.cashSales.toLocaleString()}}</strong></article><article class="stat"><span>Credit sales recorded</span><strong>UGX {{data.creditSales.toLocaleString()}}</strong></article><article class="stat"><span>Customers owe</span><strong>UGX {{data.customerOwed.toLocaleString()}}</strong></article><article class="stat"><span>Business owes suppliers/creditors</span><strong>UGX {{data.creditorOwed.toLocaleString()}}</strong></article><article class="stat"><span>Recorded expenses</span><strong>UGX {{data.expenses.toLocaleString()}}</strong></article><article class="stat"><span>Inventory at cost</span><strong>{{data.stockCost===null?'Restricted':'UGX '+data.stockCost.toLocaleString()}}</strong></article></div></section></template>
